function avg(entries){ if(!entries||!entries.length) return 0; var s=0; for(var i=0;i<entries.length;i++) s+=entries[i].m; return Math.round(s/entries.length*10)/10; }
function last7(entries){ return entries.slice().sort(function(a,b){ return a.day<b.day?1:-1; }).slice(0,7); }
function total(entries){ var s=0; for(var i=0;i<entries.length;i++) s+=entries[i].m; return s; }
function summarize(entries){ return {avg:avg(entries), total:total(entries), days:entries.length, last7:last7(entries)}; }
var EXPORTS={avg:avg, last7:last7, total:total, summarize:summarize};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ScreenTimeForgePure = EXPORTS; }
